<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/** Aerial line branch ("krak") made of surveyed poles, generated by PoleBranchService. */
class PoleBranch extends Model
{
    protected $fillable = ['project_id', 'parent_id', 'from_point_id', 'code', 'depth', 'sort_order', 'pole_count', 'length_m', 'long_spans', 'max_span_m', 'odf_id', 'route_id', 'entry_lat', 'entry_lng', 'entry_length_m'];

    protected function casts(): array
    {
        return [
            'long_spans' => 'array',
            'length_m' => 'float',
            'max_span_m' => 'float',
            'entry_lat' => 'float',
            'entry_lng' => 'float',
            'entry_length_m' => 'float',
        ];
    }

    /** @return BelongsTo<Project, $this> */
    public function project(): BelongsTo
    {
        return $this->belongsTo(Project::class);
    }

    /** @return BelongsTo<PoleBranch, $this> */
    public function parent(): BelongsTo
    {
        return $this->belongsTo(self::class, 'parent_id');
    }

    /** @return BelongsTo<Odf, $this> */
    public function odf(): BelongsTo
    {
        return $this->belongsTo(Odf::class);
    }

    /** @return BelongsTo<SurveyPoint, $this> */
    public function fromPoint(): BelongsTo
    {
        return $this->belongsTo(SurveyPoint::class, 'from_point_id');
    }

    /** @return HasMany<SurveyPoint, $this> */
    public function poles(): HasMany
    {
        return $this->hasMany(SurveyPoint::class, 'pole_branch_id')->orderBy('branch_position')->orderBy('id');
    }
}
